SECTION = lambda secs: F('사례 섹션 작성', ['섹션', '첫 문장(결론)', '넣은 근거 · 그림', '근거 출처(카드 · 측정표 번호)'],
                         fixed=secs)
LECT = lambda rows: F('강의 메모', ['메모할 것', '내 말로 한 줄', '내 작업 어디에 쓰나'], fixed=rows)
